inline std::vector<Run> build_runs(const std::vector<Route>& routes) {
    std::size_t n = routes.size();
    std::vector<Bound> bs(n), be(n);
    for (std::size_t i = 0; i < n; ++i) {
        const Route& r = routes[i];
        Key size;
        if (r.length == 0) { bs[i] = {Key(0), false}; be[i] = {Key(0), true}; }
        else {
            size = Key(1) << (128 - r.length);
            bs[i] = {r.start, false};
            Key e = r.start + size;
            be[i] = (e < r.start) ? Bound{Key(0), true} : Bound{e, false};
        }
    }
    std::vector<Bound> pts;
    pts.push_back({Key(0), false});
    for (i) { pts.push_back(bs[i]); pts.push_back(be[i]); }
    sort pts by cmpBound; unique.
    // routes sorted by start
    std::vector<int> ord(n); iota; sort by (bs[ord] < bs[ord']);
    // heap of (length, index)
    std::priority_queue<std::pair<int,int>> pq;
    std::size_t ri = 0;
    std::vector<Run> runs;
    for (std::size_t p = 0; p + 1 < pts.size(); ++p) {
        // interval [pts[p], pts[p+1])
        while (ri < n && cmpBound(bs[ord[ri]], pts[p]) <= 0) { pq.push({routes[ord[ri]].length, ord[ri]}); ++ri; }
        while (!pq.empty() && cmpBound(be[pq.top().second], pts[p]) <= 0) pq.pop();
        int hop = pq.empty() ? -1 : routes[pq.top().second].hop;
        if (!runs.empty() && runs.back().hop == hop) continue;  // coalesce
        runs.push_back({pts[p].v, hop});
    }
    // The last point is U; the loop above goes to pts.size()-2.
    return runs;
}
