inline PImage decode_image(const unsigned char* raw, std::size_t len) {
    if (len < 128 || len % 64) throw std::runtime_error("image size");
    if (std::memcmp(raw, "FIDX", 4) != 0 || raw[4] != 2) throw std::runtime_error("magic");
    for (int i = 5; i < 8; ++i) if (raw[i]) throw ...;
    std::uint32_t R = rd32(raw+8), nodes = rd32(raw+12), hopoff = rd32(raw+16), total = rd32(raw+20);
    if (total != len) throw ...;
    for (int i = 24; i < 64; ++i) if (raw[i]) throw ...;
    if (hopoff % 64 || hopoff > len) throw ...;
    PImage img; img.R = R; img.byoff.assign(len/64, -1);
    // hops
    for (std::uint32_t i = 0; i < R; ++i) { std::uint32_t v = rd32(raw+hopoff+4*i); img.hops.push_back(v == 0xffffffffu ? -1 : int(v)); }
    std::uint32_t off = 64;
    for (std::uint32_t i = 0; i < nodes; ++i) {
        if (off + 32 > hopoff) throw ...;
        PNode n; n.off = off;
        n.kind = raw[off]; n.mode = raw[off+1]; n.cached = raw[off+2];
        n.lo = rd16(raw+off+4); n.span = rd16(raw+off+6); int cnt = rd16(raw+off+8);
        std::uint32_t alloc = rd32(raw+off+12);
        if (n.kind == 0) {
            int b = cnt; if (b < 2 || b > 9) throw ...;
            std::size_t used = 32 + 4*b + std::size_t(b-1)*WIDTH[n.mode];
            const unsigned char* q = raw+off+32;
            for (int c = 0; c < b; ++c) n.children.push_back(rd32(q+4*c));
            q += 4*b;
            Key base = rd128(raw+off+16);
            for (int c = 0; c < b-1; ++c) { Key k = decode_key(q, n.mode, base); n.keys.push_back(k); q += WIDTH[n.mode]; }
        } else {
            if (cnt != n.span || n.span < 1 || n.span > 8) throw ...;
            std::size_t used = 32 + std::size_t(n.span)*WIDTH[n.mode];
            const unsigned char* q = raw+off+32;
            Key base = rd128(raw+off+16);
            for (int c = 0; c < n.span; ++c) { n.keys.push_back(decode_key(q, n.mode, base)); q += WIDTH[n.mode]; }
